-- Diver medical: no duplicate 45+ / shorter labels
UPDATE form_templates SET schema_json='{"key":"diver_medical","consent":{"required":true,"version":"dm-v2","text":{"en":"Scuba needs good physical health. Answer honestly. If pregnant, do not dive. Yes on #3, #5, #10, or any follow-up box means a physician must clear you before diving.","es":"El buceo requiere buena salud física. Responde con honestidad. Si está embarazada, no bucee. Sí en #3, #5, #10 o cualquier casilla de seguimiento implica autorización médica antes de bucear."}},"sections":[{"id":"dm","title":{"en":"Medical questionnaire","es":"Cuestionario médico"},"fields":[{"key":"over_45","type":"yes_no","required":true,"label":{"en":"I am 45 years of age or older","es":"Tengo 45 años o más"}},{"key":"dm_q1","type":"yes_no","required":true,"sensitive":true,"label":{"en":"1. Problems with lungs, breathing, heart, blood, or a COVID-19 diagnosis?","es":"1. ¿Problemas de pulmones, respiración, corazón, sangre, o diagnóstico de COVID-19?"}},{"key":"dm_box_A","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A — Chest/heart surgery or collapsed lung; asthma/allergies limiting exercise (past year); heart illness or heart meds; bronchitis/emphysema; COVID-19?","es":"Casilla A — Cirugía de pecho/corazón o pulmón colapsado; asma/alergias que limitan ejercicio (último año); enfermedad o medicación cardíaca; bronquitis/enfisema; COVID-19?"}},{"key":"dm_box_B","type":"yes_no","sensitive":true,"show_if":{"field":"over_45","op":"eq","value":"yes"},"label":{"en":"Box B (45+) — Smoke/nicotine; high cholesterol; high blood pressure; close relative died of heart disease or stroke before 50?","es":"Casilla B (45+) — ¿Fumo/nicotina; colesterol alto; presión alta; familiar cercano falleció por corazón o ACV antes de 50?"}},{"key":"dm_q3","type":"yes_no","required":true,"sensitive":true,"label":{"en":"3. Trouble with moderate exercise (e.g. walk 1 mile in 14 min, or swim 200 m without rest), or unable to do normal activity for 